-- 成果撤稿/更正状态来源凭证与不可变核验审计。
-- 状态本身仍保留在“科研成果治理”；本迁移只增加可追溯的状态事件，
-- 不修改成果原始记录、不删除治理历史，也不把未核验来源标记为已核验。
BEGIN;

CREATE TABLE IF NOT EXISTS "科研成果状态凭证" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "成果类型" integer NOT NULL,
    "成果编号" integer NOT NULL,
    "原状态" varchar(10),
    "新状态" varchar(10) NOT NULL,
    "事件类型" varchar(20) NOT NULL,
    "来源类型" varchar(30) NOT NULL,
    "来源凭证编号" varchar(200) NOT NULL,
    "来源凭证摘要" varchar(1000) NOT NULL,
    "来源文件路径" varchar(500),
    "来源文件SHA256" varchar(64),
    "来源系统" varchar(100),
    "操作人编号" integer NOT NULL,
    "操作时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研成果状态凭证" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_科研成果状态凭证_类型" CHECK ("成果类型" BETWEEN 1 AND 4),
    CONSTRAINT "ck_科研成果状态凭证_状态" CHECK ("新状态" IN ('待更正','已更正','已撤稿','有效','重复')),
    CONSTRAINT "ck_科研成果状态凭证_事件" CHECK ("事件类型" IN ('更正通知','更正完成','撤稿通知','撤稿撤回','恢复有效','重复合并','历史导入')),
    CONSTRAINT "ck_科研成果状态凭证_状态事件" CHECK (
        ("新状态" = '待更正' AND "事件类型" = '更正通知') OR
        ("新状态" = '已更正' AND "事件类型" = '更正完成') OR
        ("新状态" = '已撤稿' AND "事件类型" = '撤稿通知') OR
        ("新状态" = '有效' AND "事件类型" IN ('撤稿撤回','恢复有效','历史导入')) OR
        ("新状态" = '重复' AND "事件类型" IN ('重复合并','历史导入'))
    ),
    CONSTRAINT "ck_科研成果状态凭证_编号" CHECK (length(btrim("来源凭证编号")) BETWEEN 1 AND 200),
    CONSTRAINT "ck_科研成果状态凭证_摘要" CHECK (length(btrim("来源凭证摘要")) BETWEEN 1 AND 1000),
    CONSTRAINT "ck_科研成果状态凭证_SHA256" CHECK ("来源文件SHA256" IS NULL OR "来源文件SHA256" ~ '^[0-9A-Fa-f]{64}$'),
    CONSTRAINT "ck_科研成果状态凭证_文件" CHECK ("来源文件SHA256" IS NULL OR NULLIF(btrim("来源文件路径"), '') IS NOT NULL),
    CONSTRAINT "fk_科研成果状态凭证_操作人" FOREIGN KEY ("操作人编号") REFERENCES "人员" ("编号")
);
CREATE INDEX IF NOT EXISTS "ix_科研成果状态凭证_成果时间"
    ON "科研成果状态凭证" ("成果类型", "成果编号", "操作时间" DESC, "编号" DESC);
CREATE INDEX IF NOT EXISTS "ix_科研成果状态凭证_状态"
    ON "科研成果状态凭证" ("新状态", "事件类型", "操作时间" DESC);

COMMENT ON TABLE "科研成果状态凭证" IS '撤稿、更正和恢复等治理状态的来源凭证事件；记录创建后不可更新或删除，未核验不等于已核验';

CREATE TABLE IF NOT EXISTS "科研成果状态凭证核验" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "状态凭证编号" bigint NOT NULL,
    "核验结果" varchar(10) NOT NULL,
    "核验说明" varchar(1000) NOT NULL,
    "核验人编号" integer NOT NULL,
    "核验时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研成果状态凭证核验" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_科研成果状态凭证核验_凭证" FOREIGN KEY ("状态凭证编号") REFERENCES "科研成果状态凭证" ("编号"),
    CONSTRAINT "fk_科研成果状态凭证核验_核验人" FOREIGN KEY ("核验人编号") REFERENCES "人员" ("编号"),
    CONSTRAINT "ck_科研成果状态凭证核验_结果" CHECK ("核验结果" IN ('已核验','不通过')),
    CONSTRAINT "ck_科研成果状态凭证核验_说明" CHECK (length(btrim("核验说明")) BETWEEN 1 AND 1000)
);
CREATE INDEX IF NOT EXISTS "ix_科研成果状态凭证核验_凭证时间"
    ON "科研成果状态凭证核验" ("状态凭证编号", "核验时间" DESC, "编号" DESC);

-- 两张凭证表均为追加式审计记录；纠正错误应新增事件/核验记录，禁止覆盖原始证据。
CREATE OR REPLACE FUNCTION "fn_科研成果状态凭证_只读"()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION '科研成果状态凭证及核验记录为不可变审计数据，请新增更正事件，不得更新或删除';
END;
$$;
DROP TRIGGER IF EXISTS "tr_科研成果状态凭证_只读" ON "科研成果状态凭证";
CREATE TRIGGER "tr_科研成果状态凭证_只读"
BEFORE UPDATE OR DELETE ON "科研成果状态凭证"
FOR EACH ROW EXECUTE FUNCTION "fn_科研成果状态凭证_只读"();
DROP TRIGGER IF EXISTS "tr_科研成果状态凭证核验_只读" ON "科研成果状态凭证核验";
CREATE TRIGGER "tr_科研成果状态凭证核验_只读"
BEFORE UPDATE OR DELETE ON "科研成果状态凭证核验"
FOR EACH ROW EXECUTE FUNCTION "fn_科研成果状态凭证_只读"();

-- 对既有撤稿/更正治理快照保留“待补录”事件，不伪造真实来源凭证。
INSERT INTO "科研成果状态凭证" (
    "成果类型", "成果编号", "原状态", "新状态", "事件类型", "来源类型",
    "来源凭证编号", "来源凭证摘要", "操作人编号", "操作时间"
)
SELECT g."成果类型", g."成果编号", NULL, g."状态",
       CASE g."状态" WHEN '待更正' THEN '更正通知' WHEN '已更正' THEN '更正完成' ELSE '撤稿通知' END,
       '历史迁移', concat('MIGRATION-086-', g."编号"),
       '迁移 086 仅保留既有治理状态，原始撤稿/更正凭证待补录和核验', g."操作人编号", g."操作时间"
  FROM "科研成果治理" g
 WHERE g."状态" IN ('待更正','已更正','已撤稿')
   AND NOT EXISTS (
       SELECT 1 FROM "科研成果状态凭证" e
        WHERE e."成果类型" = g."成果类型" AND e."成果编号" = g."成果编号"
          AND e."来源类型" = '历史迁移'
   );

ALTER TABLE "科研成果治理"
    ADD COLUMN IF NOT EXISTS "状态凭证编号" bigint;
ALTER TABLE "科研成果治理"
    DROP CONSTRAINT IF EXISTS "fk_科研成果治理_状态凭证";
ALTER TABLE "科研成果治理"
    ADD CONSTRAINT "fk_科研成果治理_状态凭证"
    FOREIGN KEY ("状态凭证编号") REFERENCES "科研成果状态凭证" ("编号");

UPDATE "科研成果治理" g
   SET "状态凭证编号" = e."编号"
  FROM "科研成果状态凭证" e
 WHERE g."状态" IN ('待更正','已更正','已撤稿')
   AND g."状态凭证编号" IS NULL
   AND e."成果类型" = g."成果类型"
   AND e."成果编号" = g."成果编号"
   AND e."来源类型" = '历史迁移';

ALTER TABLE "科研成果治理"
    DROP CONSTRAINT IF EXISTS "ck_科研成果治理_状态凭证";
ALTER TABLE "科研成果治理"
    ADD CONSTRAINT "ck_科研成果治理_状态凭证"
    CHECK ("状态" NOT IN ('待更正','已更正','已撤稿') OR "状态凭证编号" IS NOT NULL);

CREATE OR REPLACE FUNCTION "fn_科研成果治理_凭证一致性"()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_type integer;
    v_id integer;
    v_status varchar(10);
BEGIN
    IF NEW."状态凭证编号" IS NULL THEN
        IF NEW."状态" IN ('待更正','已更正','已撤稿') THEN
            RAISE EXCEPTION '撤稿或更正状态必须绑定来源凭证事件';
        END IF;
        RETURN NEW;
    END IF;
    SELECT "成果类型", "成果编号", "新状态"
      INTO v_type, v_id, v_status
      FROM "科研成果状态凭证"
     WHERE "编号" = NEW."状态凭证编号";
    IF NOT FOUND OR v_type <> NEW."成果类型" OR v_id <> NEW."成果编号" OR v_status <> NEW."状态" THEN
        RAISE EXCEPTION '治理状态与来源凭证事件不匹配';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS "tr_科研成果治理_凭证一致性" ON "科研成果治理";
CREATE TRIGGER "tr_科研成果治理_凭证一致性"
BEFORE INSERT OR UPDATE ON "科研成果治理"
FOR EACH ROW EXECUTE FUNCTION "fn_科研成果治理_凭证一致性"();

UPDATE "系统迁移版本"
   SET "版本" = 86,
       "脚本" = '086_achievement_status_evidence.sql',
       "检查摘要" = '增加成果撤稿更正状态来源凭证、追加式核验审计并阻止未留证据的状态写入',
       "应用时间" = CURRENT_TIMESTAMP
 WHERE "编号" = 1;

COMMIT;
